/** Live Neo4j/APOC plus production model HTTP and SQL worker checkpoints, from actual Go Asynq. */
class GraphExtractionGoParityIT {
  @TempDir Path temp;final ObjectMapper json=new ObjectMapper();static Driver driver;
  static {try{com.tencent.weknora.retrieval.NativeDatabaseRuntime.initialize();}catch(java.sql.SQLException e){throw new ExceptionInInitializerError(e);}}
  @BeforeAll static void connect(){String uri=System.getProperty("weknora.graph.test.uri","");assertThat(uri).as("explicit isolated Neo4j/APOC URI required; this test never silently skips").isNotEmpty();driver=GraphDatabase.driver(uri,AuthTokens.none(),Config.builder().withConnectionTimeout(1,TimeUnit.SECONDS).withMaxTransactionRetryTime(0,TimeUnit.SECONDS).build());driver.verifyConnectivity();try(var s=driver.session()){assertThat(s.run("RETURN apoc.version() AS version").single().get("version").asString()).isNotBlank();}}
  @AfterAll static void close(){if(driver!=null)driver.close();}
  @TestFactory Stream<DynamicTest> productionGoGraphWorker()throws Exception{JsonNode cases;try(var in=getClass().getResourceAsStream("/go-graph-extraction.json")){cases=json.readTree(in);}assertThat(cases.size()).isEqualTo(42);var sequence=new AtomicInteger();return StreamSupport.stream(cases.spliterator(),false).map(row->DynamicTest.dynamicTest(row.path("name").asText(),()->compare(row,sequence.incrementAndGet())));}
  void compare(JsonNode oracle,int caseNo)throws Exception {
    String name=oracle.path("name").asText();try(var s=driver.session()){s.run("MATCH(n) WHERE n.kg IN ['graph-oracle-doc','foreign-document'] DETACH DELETE n").consume();}
    var f=new DocumentProcessingCompatibilityTest();f.temp=temp;f.database(caseNo,true);var k=f.seed(json.createObjectNode().put("state","finalizing"));
    f.jdbc.update("UPDATE knowledge_bases SET id='graph-oracle-kb',summary_model_id='summary',indexing_strategy=?,extract_config=? WHERE id='kb'",json.writeValueAsBytes(json.createObjectNode().put("graph_enabled",true)),json.writeValueAsBytes(config(name)));f.jdbc.update("UPDATE knowledges SET id='graph-oracle-doc',knowledge_base_id='graph-oracle-kb',title='Graph document',summary_status='completed',pending_subtasks_count=2,error_message='old error' WHERE id='knowledge'");
    if(Set.of("cancelled","deleting").contains(name))f.jdbc.update("UPDATE knowledges SET parse_status=?",name);
    if(name.equals("override"))f.jdbc.update("UPDATE knowledges SET metadata=?","{\"process_overrides\":{\"extract_config\":{\"enabled\":true,\"text\":\"Document example\",\"tags\":[\"uses\"],\"custom_instructions\":\" Override entities \"}}}");
    f.jdbc.update("INSERT INTO chunks(id,tenant_id,knowledge_id,knowledge_base_id,content,chunk_type,is_enabled,content_revision,seq_id,chunk_index,start_at,end_at,parent_chunk_id,status,source_content) VALUES('graph-oracle-chunk',1,'graph-oracle-doc','graph-oracle-kb','Alice owns the release process 中文.','text',true,4,1,0,0,34,'',0,'')");f.jdbc.update("UPDATE chunks SET content=?",oracle.path("content").asText());if(name.equals("foreign-document"))f.jdbc.update("UPDATE chunks SET knowledge_id='foreign-document'");if(name.equals("foreign-kb"))f.jdbc.update("UPDATE chunks SET knowledge_base_id='foreign-kb'");if(name.equals("foreign-tenant"))f.jdbc.update("UPDATE chunks SET tenant_id=2");if(name.equals("missing-chunk"))f.jdbc.update("DELETE FROM chunks");
    var reads=new KnowledgeProcessingSpanRepository(f.jdbc,json);var tracker=new KnowledgeProcessingSpanTracker(new KnowledgeProcessingSpanWriteRepository(f.jdbc,json,reads),json);var attempt=tracker.open(1,"graph-oracle-doc","graph-oracle");tracker.beginStage(1,"graph-oracle-doc",attempt.number(),"postprocess",null);if(name.equals("superseded"))tracker.open(1,"graph-oracle-doc","successor");if(name.equals("missing-base"))f.jdbc.update("DELETE FROM knowledge_bases WHERE id='graph-oracle-kb'");if(name.equals("base-foreign-tenant"))f.jdbc.update("UPDATE knowledge_bases SET tenant_id=2 WHERE id='graph-oracle-kb'");if(name.equals("missing-knowledge"))f.jdbc.update("DELETE FROM knowledges");
    var requests=Collections.synchronizedList(new ArrayList<JsonNode>());var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/v1/",exchange->{try{var body=json.readTree(exchange.getRequestBody());requests.add(json.createObjectNode().put("path",exchange.getRequestURI().getPath()).set("body",body));if(name.equals("cancel-during-error"))f.jdbc.update("UPDATE knowledges SET parse_status='cancelled'");int status=name.startsWith("chat-error")||name.equals("cancel-during-error")?502:200;ObjectNode response;if(status!=200)response=json.createObjectNode().set("error",json.createObjectNode().put("message","synthetic provider failure"));else{switch(name){case "binding-during-chat"->f.jdbc.update("UPDATE chunks SET knowledge_id='foreign-document'");case "cancel-during-chat"->f.jdbc.update("UPDATE knowledges SET parse_status='cancelled'");case "superseded-during-chat"->tracker.open(1,"graph-oracle-doc","successor");case "revision-during-chat"->f.jdbc.update("UPDATE chunks SET content_revision=5");case "disappeared-during-chat"->f.jdbc.update("DELETE FROM chunks");}response=json.createObjectNode().set("choices",json.createArrayNode().add(json.createObjectNode().put("index",0).put("finish_reason","stop").set("message",json.createObjectNode().put("role","assistant").put("content",oracle.path("reply").asText()))));}byte[] bytes=json.writeValueAsBytes(response);exchange.getResponseHeaders().set("Content-Type","application/json");exchange.sendResponseHeaders(status,bytes.length);try(var out=exchange.getResponseBody()){out.write(bytes);}}finally{exchange.close();}});server.start();
    var env=new MockEnvironment().withProperty("SSRF_WHITELIST","127.0.0.1").withProperty("SSRF_DNS_WHITELIST_ONLY","true");var models=new ModelClientFactory(f.jdbc,json,new GoSecretCodec(""),new ModelCatalogRuntime(f.jdbc,"","/nonexistent"),new ModelEgressPolicy(f.jdbc,json,env),env);Driver bad=null;
    try{var params=json.createObjectNode().put("provider","generic").put("base_url","http://127.0.0.1:"+server.getAddress().getPort()+"/v1").put("api_key","synthetic-key");f.jdbc.update("INSERT INTO models(id,tenant_id,name,type,source,parameters,is_builtin,status) VALUES('summary',1,'unknown','KnowledgeQA','remote',?,false,'active')",json.writeValueAsBytes(params));var baseJob=f.job(k,"chunk:extract");f.jdbc.update("UPDATE java_task_jobs SET payload=?,attempts=? WHERE id=?",oracle.path("payload").toString(),oracle.path("retry").asInt()+1,baseJob.id());var job=f.tasks.get(1,baseJob.id()).orElseThrow();var repository=new GraphExtractionRepository(f.jdbc,json,f.knowledge,f.manager,Clock.systemUTC());GraphExtractionStore store=new Neo4jGraphRepository(driver,json);if(name.startsWith("graph-error")){bad=GraphDatabase.driver("bolt://127.0.0.1:1",AuthTokens.none(),Config.builder().withConnectionTimeout(1,TimeUnit.SECONDS).withMaxTransactionRetryTime(0,TimeUnit.SECONDS).build());store=new Neo4jGraphRepository(bad,json);}var handler=new GraphExtractionHandler(repository,json,(owner,id)->models.chat(new AuthContext("system-task",owner,"viewer",false,null,false,Set.of(),Set.of()),id),store,tracker,new GraphExtractionText(json,oracle.path("description").asText()));Exception failure=null;try{handler.execute(job,f.cancellation(job));}catch(Exception e){failure=e;}
      assertThat(failure!=null).as("worker retry/ACK: %s",failure).isEqualTo(oracle.path("failed").asBoolean());assertThat(numbers(json.valueToTree(requests))).as("actual provider wire messages/options").isEqualTo(numbers(oracle.path("requests")));
      var state=f.jdbc.queryForList("SELECT parse_status,summary_status,pending_subtasks_count,error_message FROM knowledges WHERE id='graph-oracle-doc'");JsonNode actual=state.isEmpty()?json.createObjectNode().put("parse_status","").put("summary_status","").put("pending_subtasks_count",0).put("error_message",""):json.valueToTree(state.getFirst());assertThat(numbers(actual)).as("shared document terminal checkpoint").isEqualTo(numbers(oracle.path("knowledge")));
      var live=new Neo4jGraphRepository(driver,json);assertThat(numbers(live.counts("graph-oracle-kb","graph-oracle-doc"))).as("actual Neo4j counts").isEqualTo(numbers(oracle.path("counts")));var detail=live.detail("graph-oracle-kb","graph-oracle-doc","graph-oracle-chunk");for(var n:detail.path("nodes"))((ObjectNode)n).put("id","");for(var r:detail.path("relations"))((ObjectNode)r).put("id","");assertThat(numbers(detail)).as("actual Neo4j properties/provenance/relations").isEqualTo(numbers(oracle.path("detail")));
      var spans=f.jdbc.queryForList("SELECT name,status,input,output,error_code FROM knowledge_processing_spans WHERE name LIKE 'postprocess.graph.chunk[%]' ORDER BY created_at");JsonNode span=NullNode.instance;if(!spans.isEmpty()){var row=spans.getLast();var p=json.createObjectNode();for(String field:List.of("name","status","error_code"))p.put(field,Objects.toString(row.get(field),""));for(String field:List.of("input","output")){Object raw=row.get(field);p.set(field,raw==null?NullNode.instance:json.readTree(raw instanceof byte[] bytes?bytes:raw.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)));}span=p;}assertThat(numbers(span)).as("real Go tracker input/output/status/error").isEqualTo(numbers(oracle.path("span")));
    }finally{models.close();server.stop(0);if(bad!=null)bad.close();}
  }
  ObjectNode config(String name){var c=json.createObjectNode().put("enabled",!name.equals("disabled")).put("text","Example text");c.set("tags",json.createArrayNode().add("owns"));c.set("nodes",json.createArrayNode().add(json.createObjectNode().put("name","Example").set("attributes",json.createArrayNode().add("sample"))));c.set("relations",json.createArrayNode().add(json.createObjectNode().put("node1","Example").put("node2","Other").put("type","owns")));if(name.equals("custom-percent"))c.put("custom_instructions","  Retain 10% growth, literal %s and %q, %% and 100%  ");if(name.equals("custom"))c.put("custom_instructions","  Contract entities 中文  ");return c;}
  JsonNode numbers(JsonNode n){if(n.isNumber())return DecimalNode.valueOf(n.decimalValue().stripTrailingZeros());if(n.isArray()){var a=json.createArrayNode();n.forEach(v->a.add(numbers(v)));return a;}if(n.isObject()){var a=json.createObjectNode();n.fields().forEachRemaining(e->a.set(e.getKey(),numbers(e.getValue())));return a;}return n;}
}
